-- 旅行社区首批公开分享：五个分类各 10 篇，供社区、灵感包和 AI 引用直接使用。
INSERT INTO tm_travel_note
  (id, user_id, city_id, title, content, visibility, status, topic, tags, deleted)
VALUES
  -- 吃什么
  (8101, 1001, 2001, '杭州早茶别只盯网红店，这份西湖边早餐够用', '住在西湖东边时，我连续两天把早餐安排在步行十分钟内：一份葱包桧配豆浆，再慢慢走去湖边。八点前人不多，吃完去断桥也不会赶。想拍照可以带杯热茶，别空腹排长队。', 'public', 1, 'food', '杭州,早餐,西湖,小吃', 0),
  (8102, 1001, 2003, '成都火锅点菜小心得：两个人别贪多', '两个人点锅底、三样荤菜、两样素菜已经很够。微辣对不常吃辣的人也有后劲，冰粉要早点点。我们晚饭前六点到店，吃完还能慢悠悠去九眼桥看夜景。', 'public', 1, 'food', '成都,火锅,双人,夜景', 0),
  (8103, 1001, 2002, '北京胡同里的一顿早餐，豆汁可以先小口试', '在东四附近逛胡同时，先点焦圈和烧饼，再决定要不要尝豆汁。味道确实很特别，但店里大爷很热情。早餐后沿胡同散步到雍和宫，路线短，胃也舒服。', 'public', 1, 'food', '北京,胡同,早餐,本地味道', 0),
  (8104, 1001, 2023, '重庆小面别只吃麻辣，清汤也很惊喜', '早上坐轻轨前找了家小面馆，要了二两清汤加豌杂。汤头很鲜，辣椒可以自己慢慢加。山城走路耗体力，先吃一碗热面比空腹赶景点舒服很多。', 'public', 1, 'food', '重庆,小面,早餐,轻松旅行', 0),
  (8105, 1001, 2020, '广州早茶的正确打开方式：早到、少点、慢慢聊', '我们九点前到茶楼，靠窗位置还有选择。虾饺、叉烧包和一份肠粉足够两个人分，别一次点太满，后面再加喜欢的。喝完茶去永庆坊，时间刚好。', 'public', 1, 'food', '广州,早茶,粤菜,永庆坊', 0),
  (8106, 1001, 2027, '西安回民街怎么吃才不踩雷', '别从街口一路买到头，先选一碗牛肉泡馍坐下来，再留胃给甑糕和酸梅汤。傍晚人多但烟火气最好，吃完走到城墙南门散步，刚好消食。', 'public', 1, 'food', '西安,回民街,小吃,夜游', 0),
  (8107, 1001, 2018, '武汉过早一上午吃不完，三样就够', '热干面一定趁热拌开，搭配一杯豆浆会顺口很多。我们还分了一份糯米鸡，吃完直接去江汉路慢慢逛。第一次来不要把小吃当打卡任务，留点胃吃午饭。', 'public', 1, 'food', '武汉,过早,热干面,江汉路', 0),
  (8108, 1001, 2019, '长沙夜宵不只有臭豆腐，这家搭配更舒服', '晚上逛完橘子洲回来，点一份口味虾和清炒时蔬，两个人刚好。臭豆腐可以当加餐，别一上来就点大份。夏天坐室外有点热，选有空调的店更轻松。', 'public', 1, 'food', '长沙,夜宵,口味虾,橘子洲', 0),
  (8109, 1001, 2025, '昆明吃菌子先问清楚做法和等待时间', '雨季去昆明特别想吃菌子火锅，但有些菌需要煮够时间。我们提前问了店员，耐心等二十分钟后味道很鲜。饭后在翠湖走一圈，比继续赶景点更适合晚上。', 'public', 1, 'food', '昆明,菌子火锅,雨季,翠湖', 0),
  (8110, 1001, 2033, '香港茶餐厅点单：一份主食加奶茶最实在', '早上在湾仔找茶餐厅，菠萝油配热奶茶很有满足感，午饭再吃一份焗饭即可。店里翻台快，点单前先看墙上的餐牌。吃完走去维港，路程不远。', 'public', 1, 'food', '香港,茶餐厅,湾仔,维港', 0),

  -- 住哪里
  (8111, 1001, 2001, '杭州住西湖东边还是地铁口？两晚后的选择', '第一次来更推荐西湖东边，早晚散步不用打车；预算有限就选靠地铁一号线的酒店。我们住的房间不大但隔音不错，走到湖边十五分钟，体验比追求湖景更稳。', 'public', 1, 'stay', '杭州,西湖,住宿,地铁', 0),
  (8112, 1001, 2002, '北京住胡同民宿前，先确认这三个细节', '胡同氛围确实好，但一定问清楚卫生间是否独立、行李能不能进巷子、夜间隔音怎么样。我们选了靠地铁口的一家，去故宫和国博都省心，少走了不少路。', 'public', 1, 'stay', '北京,胡同,民宿,地铁', 0),
  (8113, 1001, 2003, '成都住宿选春熙路附近，适合第一次来的人', '春熙路周边吃饭和打车都方便，晚上回来也亮堂。我们没有选最热闹的主街，而是住在隔一条街的位置，安静很多。去熊猫基地早点出发也不难。', 'public', 1, 'stay', '成都,春熙路,住宿,第一次旅行', 0),
  (8114, 1001, 2023, '重庆住解放碑别只看江景，坡度更重要', '订房时看地图距离近不代表走路近，山城上坡下坡很消耗体力。我们住在解放碑地铁口附近，房间看不到江但出行很方便。想看夜景，晚上专门去洪崖洞就行。', 'public', 1, 'stay', '重庆,解放碑,地铁,夜景', 0),
  (8115, 1001, 2020, '广州住北京路附近，吃早茶和逛老城都顺路', '北京路附近适合周末短住，早上能走去茶楼，晚上回酒店也方便。我们避开临街房，睡眠好很多。行李不多的话，去沙面和永庆坊坐地铁很轻松。', 'public', 1, 'stay', '广州,北京路,老城,周末', 0),
  (8116, 1001, 2010, '哈尔滨冬天订酒店，要把暖气和位置写进备注', '冬天最怕回酒店还冷，订房前问清楚室温和是否有加湿器。中央大街附近虽然贵一点，但晚上看完冰灯回来不用折腾。我们选了有早餐的，早起省很多事。', 'public', 1, 'stay', '哈尔滨,冬天,中央大街,暖气', 0),
  (8117, 1001, 2022, '海口住海边还是骑楼附近？短途旅行这样选', '想看日落就住海边，想吃小吃和逛老街就住骑楼附近。我们只有两天，最后选了骑楼一带，晚上吃完饭走回酒店很方便，第二天再打车去海边看日落。', 'public', 1, 'stay', '海口,骑楼,海边,短途', 0),
  (8118, 1001, 2026, '拉萨第一晚别住得太远，高反时少折腾', '刚到拉萨不要把住宿订在偏远景区，选布达拉宫周边平路多、买东西方便的地方更实际。第一晚我们基本在酒店休息，房间有供氧说明会让人安心不少。', 'public', 1, 'stay', '拉萨,高反,住宿,布达拉宫', 0),
  (8119, 1001, 2031, '乌鲁木齐住市区，早市和大巴扎都更好安排', '第一次来建议住市区交通方便的位置，不必为了便宜住太远。我们早上去吃早餐，下午逛大巴扎，晚上回酒店打车不贵。房间最好选有空调的，昼夜温差会明显。', 'public', 1, 'stay', '乌鲁木齐,市区,大巴扎,交通', 0),
  (8120, 1001, 2034, '澳门住宿不用追热门酒店，半岛老城区更好逛', '如果重点是吃葡挞和看老街，住澳门半岛比住在度假村更省时间。我们选了公交站附近的小酒店，房间简单但干净，晚上走去大三巴也不累。', 'public', 1, 'stay', '澳门,半岛,老城,大三巴', 0),

  -- 去哪玩
  (8121, 1001, 2001, '杭州西湖下午这样走，避开最晒的一段', '下午从曲院风荷开始，沿湖慢慢走到北山街，太阳落一点再去断桥。全程不用强行环湖，累了就坐公交或共享单车。傍晚的湖面比正午更适合拍照。', 'public', 1, 'play', '杭州,西湖,傍晚,慢游', 0),
  (8122, 1001, 2002, '故宫半天够不够？第一次去这样安排', '提前预约上午场，从午门进、神武门出，重点看中轴线和两个感兴趣的宫殿就好。别试图每个展厅都看完，下午留给景山公园，俯瞰故宫的体验很值。', 'public', 1, 'play', '北京,故宫,景山,博物馆', 0),
  (8123, 1001, 2003, '成都看熊猫要早起，花花不一定在固定位置', '我们七点多到熊猫基地，天气还凉快，大熊猫也更活跃。别只追一只明星熊猫，沿���看幼年园反而惊喜更多。中午前离开，下午还能回市区喝茶。', 'public', 1, 'play', '成都,熊猫基地,早起,亲子', 0),
  (8124, 1001, 2011, '上海武康路半日游，别把它走成赶路打卡', '从安福路找杯咖啡开始，慢慢逛到武康大楼，再往衡山路方向走。梧桐树下适合停一停拍照，不用把每家店都进一遍。下午四点前光线柔和，人也相对少。', 'public', 1, 'play', '上海,武康路,咖啡,城市漫步', 0),
  (8125, 1001, 2012, '南京博物院和总统府只能选一个时，我选博物院', '时间只有半天的话，南京博物院更适合慢慢看，馆内空调足、展陈完整。提前预约，进馆后先拿地图。看完去附近梧桐路散步，不必再塞一个远景点。', 'public', 1, 'play', '南京,博物院,梧桐路,半日', 0),
  (8126, 1001, 2016, '济南趵突泉、大明湖一日走法，不赶也能看全', '上午先去趵突泉，人还没那么多；中午在泉城路吃饭，下午坐公交到大明湖。湖边适合慢慢坐会儿，傍晚再去曲水亭街。泉城的节奏本来就不适合赶。', 'public', 1, 'play', '济南,趵突泉,大明湖,慢游', 0),
  (8127, 1001, 2024, '贵阳夏天避暑的一天：黔灵山比商场舒服', '夏天中午别硬逛市区，早点进黔灵山，树荫多也凉快。猴子会靠近游客，食物和塑料袋收好。下午下山喝一碗冰粉，晚上再去青云市集吃小吃。', 'public', 1, 'play', '贵阳,黔灵山,避暑,夏天', 0),
  (8128, 1001, 2029, '西宁第一天别直奔远处，高原适应比景点重要', '到西宁后我们只在东关清真大寺周边和市区散步，没有立刻跑青海湖。喝水、早休息，第二天精神好很多。高原旅行留白比多打卡更重要。', 'public', 1, 'play', '西宁,高原,慢游,适应', 0),
  (8129, 1001, 2032, '台北雨天也能玩：书店、展馆和夜市排一天', '下雨时把户外行程换成诚品、博物馆和咖啡店，傍晚雨小了再去夜市。我们没有因为天气取消旅行，反而逛得更从容。鞋子选防滑的，比雨伞更关键。', 'public', 1, 'play', '台北,雨天,书店,夜市', 0),
  (8130, 1001, 2030, '银川的傍晚留给贺兰山脚下，风比想象中大', '下午晚些时候再往贺兰山方向走，阳光不刺眼，山色也更明显。外套一定带上，风起来会降温。我们没有赶两个景点，只在山脚看日落，反而很满足。', 'public', 1, 'play', '银川,贺兰山,日落,户外', 0),

  -- 路线
  (8131, 1001, 2001, '杭州两天一夜路线：西湖、灵隐、龙井不绕路', '第一天住西湖东边，上午断桥和北山街，下午坐车去灵隐；第二天早起去龙井村喝茶，午后回市区吃饭再返程。三个地方分两天安排，腿不会太累。', 'public', 1, 'route', '杭州,两天一夜,西湖,龙井', 0),
  (8132, 1001, 2004, '天津周末路线：海河夜景和五大道放一天', '周六上午逛五大道，午饭吃煎饼果子和锅巴菜；下午回酒店休息，傍晚沿海河走到解放桥。第二天再去古文化街买点伴手礼，节奏轻松也够看。', 'public', 1, 'route', '天津,周末,海河,五大道', 0),
  (8133, 1001, 2006, '太原一日慢游：晋祠别和市区景点硬拼', '上午早些去晋祠，认真看古建至少留三小时；午后回市区吃面，傍晚到汾河边散步。别把晋祠和太原博物馆都塞进同一天，交通和体力都会吃紧。', 'public', 1, 'route', '太原,晋祠,一日游,古建', 0),
  (8134, 1001, 2008, '沈阳两日路线：故宫和中街放在同一个上午', '第一天上午沈阳故宫，出门就是中街，午饭和逛街可以连着安排；下午去老北市看看。第二天再单独留给工业博物馆或棋盘山，行程不会来回穿城。', 'public', 1, 'route', '沈阳,两日游,故宫,中街', 0),
  (8135, 1001, 2014, '福州周末路线：三坊七巷配温泉，刚好放松', '周六上午进三坊七巷，午饭吃鱼丸和肉燕，下午别再赶远路，找家温泉泡一泡。周日上午去烟台山散步喝咖啡，下午返程，适合不想太累的周末。', 'public', 1, 'route', '福州,周末,三坊七巷,温泉', 0),
  (8136, 1001, 2015, '南昌一日路线：滕王阁放在傍晚更有感觉', '上午先在八一起义纪念馆附近走走，中午吃拌粉瓦罐汤；下午回酒店休息一下，傍晚再去滕王阁和赣江边。夜景亮起来后，整天的节奏会舒服很多。', 'public', 1, 'route', '南昌,一日游,滕王阁,夜景', 0),
  (8137, 1001, 2017, '郑州周末路线：博物馆和二七广场分开安排', '第一天留给河南博物院，预约到上午场后别再塞远行程；晚上去二七广场附近吃饭。第二天如果天气好再考虑黄河边，避免把市区和郊外来回折返。', 'public', 1, 'route', '郑州,周末,河南博物院,二七广场', 0),
  (8138, 1001, 2021, '南宁两天一夜：青秀山和夜市这样排', '第一天上午逛青秀山，下午回市区休息，晚上去夜市吃酸嘢和烤物；第二天睡到自然醒，再去老街慢慢逛。南宁的热天要留午休，不然下午很容易没精神。', 'public', 1, 'route', '南宁,两天一夜,青秀山,夜市', 0),
  (8139, 1001, 2028, '兰州一日路线：黄河边和牛肉面放在早上', '早上先吃一碗牛肉面，再沿黄河边走到中山桥，天气凉爽时体验最好。中午找地方休息，傍晚再看白塔山方向的落日。路线短，但兰州味道很足。', 'public', 1, 'route', '兰州,一日游,黄河,牛肉面', 0),
  (8140, 1001, 2033, '香港两日路线：港岛一天、九龙一天最省心', '第一天集中在港岛，从湾仔到维港再到太平山；第二天去尖沙咀和旺角。过海次数少，地铁和步行都更好掌控。晚餐别卡死时间，排��是常态。', 'public', 1, 'route', '香港,两日游,港岛,九龙', 0),

  -- 避坑
  (8141, 1001, 2001, '杭州西湖租车避坑：别在景区边临时还车', '西湖周边周末人多，临时找还车点很容易绕路。我们提前看好地铁站附近的停车点，最后一段走过去反而省时间。骑车适合短距离，别硬骑完整圈。', 'public', 1, 'tip', '杭州,西湖,骑行,周末', 0),
  (8142, 1001, 2002, '北京热门博物馆预约失败后，别当天碰运气', '故宫、国博这类场馆预约满了，现场通常也没法补。我们及时换成附近的胡同和公园，没有白跑一趟。出发前一晚把预约凭证截图，进场时更从容。', 'public', 1, 'tip', '北京,预约,博物馆,避坑', 0),
  (8143, 1001, 2003, '成都夏天看熊猫，防晒和驱蚊都要带', '园区树多但也闷热，上午十点后太阳很晒。我们带了小风扇和驱蚊液，排队时舒服很多。不要把零食露在外面，猴子出没的区域尤其要注意。', 'public', 1, 'tip', '成都,熊猫,夏天,防晒', 0),
  (8144, 1001, 2010, '哈尔滨冰雪大世界别穿普通运动鞋', '冰雪地面很滑，普通运动鞋踩久了脚底也冷。我们后来换了厚袜子、防滑鞋套和暖宝宝，体验立刻好很多。手机掉电快，带充电宝并贴身放比较稳。', 'public', 1, 'tip', '哈尔滨,冰雪,保暖,防滑', 0),
  (8145, 1001, 2018, '武汉夏天走江边，下午两点别硬撑', '长江边视野很好，但盛夏午后体感很晒。我们改成傍晚去江滩，风更舒服，拍黄鹤楼远景也更有层次。白天把室内馆和午饭排在一起更合理。', 'public', 1, 'tip', '武汉,夏天,江滩,防晒', 0),
  (8146, 1001, 2025, '昆明昼夜温差大，短袖外再带一件薄外套', '白天晒着会觉得热，日落后风一来就凉。我们第一晚没带外套，在滇池边坐了一会儿就受不了。薄冲锋衣不占地方，去石林或湖边都能用上。', 'public', 1, 'tip', '昆明,温差,滇池,穿搭', 0),
  (8147, 1001, 2026, '拉萨旅行别把洗澡和剧烈运动排在第一天', '刚到高原时身体需要适应，我们第一天只散步、喝水、早睡，没有洗头洗澡也没有跑景点。第二天状态稳定很多。出现明显不适要及时休息，不要硬扛。', 'public', 1, 'tip', '拉萨,高原,高反,健康', 0),
  (8148, 1001, 2027, '西安城墙骑行前，先看天气和闭园时间', '城墙上风大，夏天晒、冬天冷，下午晚些骑更舒服。租车前问清楚归还点和闭园时间，别卡着最后半小时上去。我们骑半圈就下来了，体力刚好。', 'public', 1, 'tip', '西安,城墙,骑行,天气', 0),
  (8149, 1001, 2029, '青海湖方向出发前，先确认天气再决定去不去', '高原天气变化快，晴天和大风天体验差很多。我们前一晚看预报后把出发时间提前，避开了午后的风。路上补给点不多，水和零食提前准备好。', 'public', 1, 'tip', '西宁,青海湖,天气,自驾', 0),
  (8150, 1001, 2034, '澳门过关日别把行程排得太满', '周末过关和入住都可能花时间，第一天下午只安排大三巴和老城区最稳。我们把度假村和表演留到第二天，心态轻松很多。证件和酒店订单提前放到手机首页。', 'public', 1, 'tip', '澳门,过关,周末,行程', 0)
ON DUPLICATE KEY UPDATE
  user_id = VALUES(user_id), city_id = VALUES(city_id), title = VALUES(title), content = VALUES(content),
  visibility = VALUES(visibility), status = VALUES(status), topic = VALUES(topic), tags = VALUES(tags), deleted = VALUES(deleted),
  update_time = CURRENT_TIMESTAMP;
